import { useCustomReactQuery } from '@sixshop3-fe/shared/hooks';
import { QueryOption } from '@sixshop3-fe/shared/types';
import { formatEndpoint } from '@sixshop3-fe/shared/utils';
import { QUERY_KEY, SERVER } from '@sixshop3-fe/theme-universe/constants';
import { RestockExistData, RestockExistVariable } from '@sixshop3-fe/theme-universe/types';
import { websiteApi as api, getEndpointSet, websiteAuth } from '@sixshop3-fe/theme-universe/utils';

import { endpoint } from '../../rest';

const { EXIST_RESTOCK } = getEndpointSet({
  endpoint,
  server: SERVER.GATEWAY,
  domain: 'restock',
});

export const fetchExistRestock = ({ queryParam }: RestockExistVariable) => {
  const token = websiteAuth.getToken();

  return api.get({
    endpoint: formatEndpoint(EXIST_RESTOCK),
    queryParam,
    option: token
      ? {
          headers: {
            'X-Customer-Usertoken': token,
          },
        }
      : undefined,
  });
};

const useRestockQuery = () => {
  const { useCustomQuery } = useCustomReactQuery([QUERY_KEY.RESTOCK, websiteAuth.getToken()]);

  const useGetExistRestockQuery = (
    variable: RestockExistVariable,
    option?: QueryOption<RestockExistData, RestockExistVariable['queryParam']>
  ) => {
    const { queryParam } = variable;

    return useCustomQuery<RestockExistData, RestockExistVariable['queryParam']>(
      () => fetchExistRestock({ queryParam }),
      queryParam,
      option
    );
  };

  return { useGetExistRestockQuery };
};

export default useRestockQuery;

